<!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102a5c"><title>C-Net Audio Meet</title><link rel="stylesheet" href="assets/app.css"></head>
<body><header><a class="brand" href="./"><span>CN</span><b>C-Net Audio Meet</b></a><div class="badge">Audio only • सुरक्षित • बिना समय सीमा</div></header>
<main><section id="home" class="hero"><div><p class="eyebrow">MCI EDUCATIONAL GROUP</p><h1>साफ आवाज़ में जुड़िए,<br><em>बिना वीडियो के।</em></h1><p class="lead">संस्था की बैठक, ऑनलाइन कक्षा और निजी समूह चर्चा के लिए सरल audio meeting platform.</p><div class="cards"><button class="primary" id="createBtn">नई मीटिंग शुरू कीजिए</button><div class="join"><input id="roomInput" maxlength="11" placeholder="Meeting ID"><button id="joinBtn">Join</button></div></div><p class="note">एक meeting में अधिकतम 8 सदस्य • कोई recording नहीं</p></div><aside><div class="orb">🎙️</div><h3>Privacy-first audio</h3><p>Camera बंद रहता है। बातचीत record या server पर save नहीं होती।</p></aside></section>
<section id="lobby" class="panel hidden"><h2 id="lobbyTitle">मीटिंग में जुड़िए</h2><label>आपका नाम<input id="nameInput" maxlength="60" autocomplete="name" placeholder="अपना नाम लिखिए"></label><button class="primary" id="enterBtn">Microphone के साथ जुड़िए</button><button class="linkbtn" id="backBtn">वापस जाएँ</button><p id="lobbyError" class="error"></p></section>
<section id="meeting" class="meeting hidden"><div class="topbar"><div><b id="meetingId"></b><small id="status">Connecting…</small></div><button id="copyBtn">Link copy</button></div><div id="people" class="people"></div><div id="chat" class="chat hidden"><div id="messages"></div><form id="chatForm"><input id="chatInput" maxlength="300" placeholder="संदेश लिखिए"><button>भेजें</button></form></div><div class="controls"><button id="micBtn">🎙️ Mute</button><button id="handBtn">✋ Raise hand</button><button id="chatBtn">💬 Chat</button><button id="lockBtn" class="host hidden">🔒 Lock</button><button id="endBtn" class="danger">Leave</button></div><div id="audioBox"></div></section></main>
<footer>© 2026 C-Net Audio Meet • MCI Educational Group</footer><script src="assets/app.js"></script></body></html>

